<?php
require '../config.php';require '../auth.php';require_admin();$rows=$conn->query('SELECT t.*,u.name user_name,f.facility_name FROM testimonials t JOIN users u ON u.id=t.user_id JOIN facilities f ON f.id=t.facility_id ORDER BY t.created_at DESC')->fetch_all(MYSQLI_ASSOC);$pageTitle='Testimonials';require 'partials/header.php';?>
<h1>Testimonials</h1><?php if(!$rows):?><div class="empty-state"><p>No comments yet.</p></div><?php else:?><div class="testimonial-list"><?php foreach($rows as $t):?><div class="testimonial-card"><span class="badge badge-accent"><?=htmlspecialchars($t['facility_name'])?></span><div class="testimonial-stars"><?=str_repeat('&#9733;',(int)$t['rating'])?></div><p><?=nl2br(htmlspecialchars($t['comment']))?></p><div class="testimonial-meta"><span><?=htmlspecialchars($t['user_name'])?> &middot; <?=htmlspecialchars(date('d M Y',strtotime($t['created_at'])))?></span><form method="post" action="testimonial_delete.php"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button class="btn-small btn-danger">Delete</button></form></div></div><?php endforeach;?></div><?php endif;?><?php require 'partials/footer.php';?>

